_HAS_SOUNDFILE = True

class HalfStepDownSounds:
    """Звуки для строя: Half Step Down"""

    _NOTE_NAME_MAP = {
        "Eb2": "Eb2",
        "Ab2": "Ab2",
        "Db3": "Db3",
        "Gb3": "Gb3",
        "Bb3": "Bb3",
        "Eb4": "Eb4",
    }

    @staticmethod
    def get_sound_data(note_name: str) -> Optional[bytes]:
        safe_name = HalfStepDownSounds._NOTE_NAME_MAP.get(note_name)
        if safe_name:
            var_name = f"_{safe_name}_BASE64"
            if var_name in globals():
                return base64.b64decode(globals()[var_name])
        return None

    @staticmethod
    def get_sound(note_name: str):
        if not KIVY_AVAILABLE:
            return None
        data = HalfStepDownSounds.get_sound_data(note_name)
        if data:
            try:
                ext = ".ogg" if _HAS_SOUNDFILE else ".wav"
                fd, path = tempfile.mkstemp(suffix=ext)
                os.close(fd)
                with open(path, "wb") as f:
                    f.write(data)
                sound = SoundLoader.load(path)
                def _cleanup(dt):
                    try:
                        if os.path.exists(path):
                            os.unlink(path)
                    except Exception:
                        pass
                Clock.schedule_once(_cleanup, 5.0)
                return sound
            except Exception:
                return None
        return None

    @staticmethod
    def get_all_notes() -> list:
        return list(NOTES_METADATA.keys())

